ALTER TABLE users ADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW();
ALTER TABLE requests ADD COLUMN IF NOT EXISTS requester_id BIGINT REFERENCES users(id) ON DELETE SET NULL;
ALTER TABLE requests ADD COLUMN IF NOT EXISTS approver_id BIGINT REFERENCES users(id) ON DELETE SET NULL;
ALTER TABLE requests ADD COLUMN IF NOT EXISTS approved_by BIGINT REFERENCES users(id) ON DELETE SET NULL;
ALTER TABLE requests ADD COLUMN IF NOT EXISTS approval_status TEXT NOT NULL DEFAULT 'PENDING' CHECK (approval_status IN ('PENDING','APPROVED','REJECTED'));
ALTER TABLE requests ADD COLUMN IF NOT EXISTS approval_note TEXT NOT NULL DEFAULT '';
ALTER TABLE requests ADD COLUMN IF NOT EXISTS approved_at TIMESTAMPTZ;
ALTER TABLE requests ALTER COLUMN status SET DEFAULT 'NOT_STARTED';
UPDATE requests SET status='NOT_STARTED' WHERE status IS NULL;
UPDATE requests SET status='IN_PROGRESS' WHERE LOWER(TRIM(status)) IN ('in process','in progress','in_progress');
UPDATE requests SET status='COMPLETED' WHERE LOWER(TRIM(status))='completed';
UPDATE requests SET status='NOT_STARTED' WHERE LOWER(TRIM(status)) IN ('not started','not_started');
UPDATE requests SET requester_id=u.id FROM users u WHERE requests.requester_id IS NULL AND (LOWER(requests.requester)=LOWER(u.email) OR LOWER(requests.requester)=LOWER(u.name));
UPDATE requests SET approver_id=u.id FROM users u WHERE requests.approver_id IS NULL AND (LOWER(requests.approver)=LOWER(u.email) OR LOWER(requests.approver)=LOWER(u.name));
CREATE TABLE IF NOT EXISTS notifications (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, recipient_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, actor_id BIGINT REFERENCES users(id) ON DELETE SET NULL, notification_type TEXT NOT NULL, title TEXT NOT NULL, body TEXT NOT NULL DEFAULT '', task_id BIGINT REFERENCES tasks(id) ON DELETE CASCADE, request_id BIGINT REFERENCES requests(id) ON DELETE CASCADE, read_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS audit_logs (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, actor_id BIGINT REFERENCES users(id) ON DELETE SET NULL, action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id BIGINT, details JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_notifications_recipient_unread ON notifications(recipient_id,created_at DESC) WHERE read_at IS NULL;
CREATE INDEX IF NOT EXISTS idx_audit_logs_created ON audit_logs(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_requests_approver_pending ON requests(approver_id,created_at DESC) WHERE approval_status='PENDING';
